package nl.smartstreamlabs.sbwdroneconfig;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class DistanceWarPlannerTest {
    static DistanceWarPlanner.Settings fixed(){return new DistanceWarPlanner.Settings(60,60,.30,250,700);}
    static DistanceWarPlanner.Listener p(int id,double x){return new DistanceWarPlanner.Listener(new UUID(0,id),"minecraft:overworld",x,70,0);}
    @Test void settingsClampNonfiniteAndReversedValues(){var s=new DistanceWarPlanner.Settings(-1,-50,Double.NaN,Double.POSITIVE_INFINITY,-1);assertEquals(60,s.minSeconds());assertEquals(60,s.maxSeconds());assertEquals(.30,s.volume());assertEquals(250,s.minDistance());assertEquals(250,s.maxDistance());}
    @Test void initialQuietAndFullTailBeforeNextPause(){var plan=new DistanceWarPlanner(new Random(9));var heard=new ArrayList<Long>();for(long t=0;t<5000;t+=20)for(var e:plan.tick(t,List.of(p(1,0)),fixed()))heard.add(t);assertEquals(1200,heard.get(0));for(int i=1;i<heard.size();i++){long gap=heard.get(i)-heard.get(i-1);assertTrue(gap>=1200+DistanceWarPlanner.guardTicks(0)&&gap<=1220+DistanceWarPlanner.CLIP_TICKS);}}
    @Test void nearbyPlayersReceiveOneSharedWorldSource(){var plan=new DistanceWarPlanner(new Random(2));List<DistanceWarPlanner.Event> out=new ArrayList<>();for(int t=0;t<=1200;t+=20)out.addAll(plan.tick(t,List.of(p(1,0),p(2,4)),fixed()));assertEquals(1,out.size());var e=out.get(0);assertEquals(Set.of(p(1,0).id(),p(2,4).id()),new HashSet<>(e.recipients()));double distance=Math.hypot(e.x(),e.z());assertTrue(distance>=250&&distance<=700);}
    @Test void farAreasRunIndependently(){var plan=new DistanceWarPlanner(new Random(2));for(int t=0;t<1200;t+=20)assertTrue(plan.tick(t,List.of(p(1,0),p(2,10000)),fixed()).isEmpty());var events=plan.tick(1200,List.of(p(1,0),p(2,10000)),fixed());assertEquals(2,events.size());assertTrue(events.stream().allMatch(e->e.recipients().size()==1));}
    @Test void overlappingAudiencesNeverGetDoubleBooms(){var plan=new DistanceWarPlanner(new Random(13));var last=new HashMap<UUID,Long>();int total=0;for(long t=0;t<30000;t+=20)for(var e:plan.tick(t,List.of(p(1,0),p(2,150),p(3,750)),fixed())){total++;for(var id:e.recipients()){Long old=last.put(id,t);if(old!=null)assertTrue(t-old>=1200+DistanceWarPlanner.guardTicks(0),"Overlapping area bypassed silence");}}assertTrue(total>10);}
    @Test void logoutAndReconnectStartFreshWait(){var plan=new DistanceWarPlanner(new Random(5));plan.tick(0,List.of(p(1,0)),fixed());plan.tick(1100,List.of(),fixed());assertEquals(0,plan.tracked());assertTrue(plan.tick(1200,List.of(p(1,0)),fixed()).isEmpty());assertTrue(plan.tick(2380,List.of(p(1,0)),fixed()).isEmpty());assertEquals(1,plan.tick(2400,List.of(p(1,0)),fixed()).size());}
    @Test void dimensionChangeCannotReplayAnOldDeadline(){var plan=new DistanceWarPlanner(new Random(5));plan.tick(0,List.of(p(1,0)),fixed());var next=new DistanceWarPlanner.Listener(p(1,0).id(),"minecraft:the_nether",0,70,0);assertTrue(plan.tick(1200,List.of(next),fixed()).isEmpty());assertEquals(1,plan.tick(2400,List.of(next),fixed()).size());}
    @Test void boundedAreasStillServeDistantPlayers(){var plan=new DistanceWarPlanner(new Random(1));var players=new ArrayList<DistanceWarPlanner.Listener>();for(int i=1;i<=200;i++)players.add(p(i,i*6000));var served=new HashSet<UUID>();for(int t=0;t<=2000;t+=20){var out=plan.tick(t,players,fixed());assertTrue(out.size()<=64);for(var e:out)served.addAll(e.recipients());}assertEquals(200,served.size());}
    @Test void manualExampleHasCooldownAndNoTailOverlap(){var plan=new DistanceWarPlanner(new Random(3));assertNotNull(plan.example(0,p(1,0),List.of(p(1,0)),fixed()));assertNull(plan.example(1,p(1,0),List.of(p(1,0)),fixed()));assertNull(plan.example(199,p(1,0),List.of(p(1,0)),fixed()));assertNull(plan.example(200,p(1,0),List.of(p(1,0)),fixed()));assertNotNull(plan.example(1200+DistanceWarPlanner.CLIP_TICKS,p(1,0),List.of(p(1,0)),fixed()));}
    @Test void threePlayerPreviewAcceptsImmutableInput(){var plan=new DistanceWarPlanner(new Random(8));var players=List.of(p(1,0),p(2,2),p(3,4));assertNotNull(plan.example(0,p(1,0),players,fixed()));assertNotNull(plan.example(1200+DistanceWarPlanner.CLIP_TICKS,p(1,0),players,fixed()));}
    @Test void adminToggleCannotShortenThePreviousTailAndQuietPeriod(){var plan=new DistanceWarPlanner(new Random(3));var players=List.of(p(1,0));assertNotNull(plan.example(0,p(1,0),players,fixed()));plan.clear();assertNull(plan.example(200,p(1,0),players,fixed()));assertNotNull(plan.example(1200+DistanceWarPlanner.CLIP_TICKS,p(1,0),players,fixed()));}
    @Test void worldStopClearsOldClockCooldowns(){var plan=new DistanceWarPlanner(new Random(3));var players=List.of(p(1,0));plan.example(5000,p(1,0),players,fixed());plan.resetWorld();assertNotNull(plan.example(0,p(1,0),players,fixed()));}
    @Test void clearCancelsAllFutureWork(){var plan=new DistanceWarPlanner(new Random(3));plan.tick(0,List.of(p(1,0)),fixed());plan.clear();assertEquals(0,plan.tracked());assertEquals(0,plan.areas());assertTrue(plan.tick(1200,List.of(p(1,0)),fixed()).isEmpty());}
    @Test void distanceGainIsFiniteMonotonicAndFadesOut(){assertTrue(DistanceWarPlanner.gain(250,1050)>DistanceWarPlanner.gain(700,1050));assertTrue(DistanceWarPlanner.gain(1049,1050)<.01);assertEquals(0,DistanceWarPlanner.gain(1050,1050));assertEquals(0,DistanceWarPlanner.gain(Double.NaN,1050));}
}
